@Override
    public boolean canContinueToUse() {
        if (ticksRunning >= 20 * 15) {
            starbuncle.addGoalDebug(this, new DebugEvent("BedTimeout", "Took too long to find bed"));
            starbuncle.goalState = Starbuncle.StarbuncleGoalState.NONE;
            return false;
        }

        if (bedPos == null || starbuncle.data.bedPos == null)
            return false;

        boolean bedValid = true;
        boolean isOnBed = false;
        // Time defer these checks otherwise we will destroy TPS with blockstate lookups.
        if (starbuncle.level.getGameTime() % 10 == 0) {
            bedValid = isBedValid();
            isOnBed = isOnBed();
        }

        return !unreachable && bedValid && !isOnBed;
    }

@Override
    public void start() {
        super.start();
        unreachable = false;
        starbuncle.getNavigation().stop();
        starbuncle.goalState = Starbuncle.StarbuncleGoalState.RESTING;
        ticksRunning = 0;
        bedPos = starbuncle.data.bedPos;
    }

@Override
    public void stop() {
        super.stop();
        ticksRunning = 0;
    }

@Override
    public void tick() {
        super.tick();
        ticksRunning++;
        setPath(bedPos.getX(), bedPos.getY() + 1.0, bedPos.getZ(), 1.3);
        starbuncle.addGoalDebug(this, new DebugEvent("PathToBed", "Pathing to " + bedPos.getX() + " " + bedPos.getY() + " " + bedPos.getZ()));
    }

public void setPath(double x, double y, double z, double speedIn) {
        starbuncle.getNavigation().tryMoveToBlockPos(BlockPos.containing(x, y, z), 1.3);
        if (starbuncle.getNavigation().getPath() != null && !starbuncle.getNavigation().getPath().canReach()) {
            starbuncle.addGoalDebug(this, new DebugEvent("BedUnreachable", "Unreachable"));
            unreachable = true;
        }
    }

@Override
    public boolean canUse() {
        if (starbuncle.level.random.nextInt(2) == 0) {
            return false;
        }
        bedPos = starbuncle.data.bedPos;
        if (starbuncle.getBedBackoff() > 0
                || starbuncle.goalState != Starbuncle.StarbuncleGoalState.NONE
                || bedPos == null
                || !behavior.canGoToBed()) {
            starbuncle.addGoalDebug(this, new DebugEvent("CannotSleep", "Bed not valid" + " backoff: " + starbuncle.getBedBackoff()));
            return false;
        }
        boolean canRun = isBedValid() && !isOnBed();
        if (!canRun) {
            starbuncle.setBedBackoff(20 * 3);
            starbuncle.addGoalDebug(this, new DebugEvent("InvalidBed", "Bed position invalid"));
        }
        return canRun;
    }

public boolean isBedValid() {
        return starbuncle.level.isLoaded(bedPos) && starbuncle.level.getBlockState(new BlockPos(bedPos)).is(BlockTagProvider.SUMMON_SLEEPABLE);
    }

public boolean isOnBed() {
        return starbuncle.level.getBlockState(BlockPos.containing(starbuncle.position)).is(BlockTagProvider.SUMMON_SLEEPABLE);
    }

@Override
	public void update() {

		if (this.linkedContainer == null && this.linkedContainerPos != null) {
			this.linkContainer(world.getTileEntity(this.linkedContainerPos));
		}

		// Handle shrine regeneration
		if (conquered && Wizardry.settings.shrineRegenerationEnabled && regenerationTime > 0) {
			if (world.getTotalWorldTime() >= regenerationTime) {
				regenerate();
				return; // Don't process other logic during regeneration
			}
		}

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!activated && !conquered && world.getClosestPlayer(x, y, z, ACTIVATION_RADIUS, false) != null && (lastRegenerationTime == 0 || world.getTotalWorldTime() - lastRegenerationTime > 100)) { // 5 second delay after regeneration

			this.activated = true;

			if (world.isRemote) {
				ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
			}

			world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

			if (!world.isRemote) {

				EntityEvilWizard[] wizards = new EntityEvilWizard[linkedWizards.length];

				for (int i = 0; i < linkedWizards.length; i++) {

					EntityEvilWizard wizard = new EntityEvilWizard(world);

					float angle = world.rand.nextFloat() * 2 * (float) Math.PI;
					double x1 = this.pos.getX() + 0.5 + 5 * MathHelper.sin(angle);
					double z1 = this.pos.getZ() + 0.5 + 5 * MathHelper.cos(angle);
					Integer y1 = BlockUtils.getNearestFloor(world, new BlockPos(x1, this.pos.getY(), z1), 8);
					if (y1 == null) {
						// Fallback to the position of the shrine core if it failed to find a position (unlikely)
						x1 = this.pos.getX() + 1; // Offset it so the wizard isn't inside the block
						y1 = this.pos.getY();
						z1 = this.pos.getZ();
					}

					wizard.setLocationAndAngles(x1, y1 + 0.5, z1, 0, 0);
					wizard.setElement(world.getBlockState(pos).getValue(BlockPedestal.ELEMENT));
					wizard.onInitialSpawn(world.getDifficultyForLocation(pos), null);
					wizard.hasStructure = true;

					world.spawnEntity(wizard);
					wizards[i] = wizard;
					linkedWizards[i] = wizard.getUniqueID();
				}

				for (EntityEvilWizard wizard : wizards) wizard.groupUUIDs.addAll(Arrays.asList(linkedWizards));
			}

			containNearbyTargets();
		}

		if (!areWizardsDead() && activated && world.getTotalWorldTime() % 20L == 0) containNearbyTargets();

		if (activated && areWizardsDead() && !world.isRemote) {
			conquer();
		}
	}

public void conquer() {

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!world.isRemote) {

			WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

			// Remove containment effects from nearby targets when shrine is conquered
			removeContainmentFromNearbyTargets();

			// If regeneration is enabled, schedule regeneration instead of removing the tile entity
			if (Wizardry.settings.shrineRegenerationEnabled) {
				this.conquered = true;
				this.regenerationTime = world.getTotalWorldTime() + (Wizardry.settings.shrineRegenerationTime * 1200L); // Convert minutes to ticks (20 ticks per second * 60 seconds)
				this.activated = false;
				Arrays.fill(this.linkedWizards, null); // Clear wizard references
				// Keep lootedPlayers list - it's permanent tracking for this shrine instance

				// Handle chest breaking and loot dropping
				handleChestLootDrop();

				// Mark the tile entity for update
				this.markDirty();

				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					// Keep the block state the same, just mark as conquered
					this.shrineElement = world.getBlockState(pos).getValue(BlockPedestal.ELEMENT);
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
			} else {
				// Original behavior: remove the tile entity
				BlockPos chestPos = this.pos.up();
				TileEntity chestTileEntity = world.getTileEntity(chestPos);
				if (chestTileEntity instanceof TileEntityChest) {
					TileEntityChest chest = (TileEntityChest) chestTileEntity;
					NBTExtras.removeUniqueId(chest.getTileData(), ArcaneLock.NBT_KEY);
					chest.markDirty();
					world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
				}
				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					world.setBlockState(pos, WizardryBlocks.runestone_pedestal.getDefaultState().withProperty(BlockPedestal.ELEMENT, world.getBlockState(pos).getValue(BlockPedestal.ELEMENT)));
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
				world.markTileEntityForRemoval(this);
			}
		}

		if (linkedContainer == null) {
			linkedContainer = world.getTileEntity(pos.up());
		}

		if (linkedContainer != null) {
			NBTExtras.removeUniqueId(linkedContainer.getTileData(), ArcaneLock.NBT_KEY);
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerMost");
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerLeast");
		}
		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_CONQUER, SoundCategory.BLOCKS, 1, 1, false);

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).scale(5).pos(x, y + 1, z).clr(0xf06495).time(12).spawn(world);
			for (int i = 0; i < 5; i++) {
				float brightness = 0.8f + world.rand.nextFloat() * 0.2f;
				ParticleBuilder.create(Type.SPARKLE, world.rand, x, y + 1, z, 1, true).clr(1, brightness, brightness).spawn(world);
			}
		}
	}

private void regenerate() {

		if (world.isRemote) return;

		// Remove containment effects from nearby targets when shrine regenerates
		removeContainmentFromNearbyTargets();

		// Reset shrine state
		this.conquered = false;
		this.regenerationTime = 0;
		this.activated = false;
		Arrays.fill(this.linkedWizards, null);
		// Keep lootedPlayers list - it's permanent for this shrine instance

		// Force a short delay before allowing reactivation to prevent immediate re-activation
		this.lastRegenerationTime = world.getTotalWorldTime();

		// Forcibly replace whatever block is above the altar with a fresh chest
		BlockPos chestPos = this.pos.up();

		// Always replace the block above with a fresh chest during regeneration
		world.setBlockState(chestPos, Blocks.CHEST.getDefaultState());

		// Set up the loot table for the shrine chest
		TileEntity chestTileEntity = world.getTileEntity(chestPos);
		if (chestTileEntity instanceof TileEntityChest) {
			TileEntityChest chest = (TileEntityChest) chestTileEntity;
			chest.setLootTable(new ResourceLocation(Wizardry.MODID, "chests/shrine"), world.rand.nextLong());
		}

		// Link and apply arcane lock to the container
		if (chestTileEntity != null) {
			this.linkContainer(chestTileEntity);
			chestTileEntity.getTileData().setUniqueId(ArcaneLock.NBT_KEY, new UUID(0, 0)); // Nil UUID for shrine lock
			chestTileEntity.markDirty(); // Mark tile entity as dirty for client sync

			// Trigger visual update for arcane lock effect
			IBlockState blockState = world.getBlockState(chestPos);
			world.markAndNotifyBlock(chestPos, null, blockState, blockState, 3);
			world.notifyBlockUpdate(chestPos, blockState, blockState, 3); // Additional client sync
		}

		// Visual and audio effects for regeneration
		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		//	WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
		}

		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

		this.markDirty();
	}

private boolean areWizardsDead() {

		for (UUID uuid : linkedWizards) {
			Entity entity = EntityUtils.getEntityByUUID(world, uuid);
			if (entity instanceof EntityEvilWizard && entity.isEntityAlive()) return false;
		}

		return true;
	}

@Override
	public NBTTagCompound writeToNBT(NBTTagCompound compound) {

		compound.setBoolean("activated", this.activated);
		compound.setBoolean("conquered", this.conquered);
		compound.setLong("regenerationTime", this.regenerationTime);
		compound.setLong("lastRegenerationTime", this.lastRegenerationTime);
		if (shrineElement != null) compound.setInteger("shrineElement", this.shrineElement.ordinal());
		if (linkedContainer != null)
			NBTExtras.storeTagSafely(compound, "linkedContainerPos", NBTUtil.createPosTag(linkedContainer.getPos()));

		NBTTagList wizardTagList = new NBTTagList();
		for (UUID uuid : linkedWizards) {
			if (uuid != null) wizardTagList.appendTag(NBTUtil.createUUIDTag(uuid));
		}
		NBTExtras.storeTagSafely(compound, "wizards", wizardTagList);

		NBTTagList playerTagList = new NBTTagList();
		for (UUID uuid : lootedPlayers) {
			playerTagList.appendTag(NBTUtil.createUUIDTag(uuid));
		}
		NBTExtras.storeTagSafely(compound, "lootedPlayers", playerTagList);

		return super.writeToNBT(compound);
	}

@Override
	public void readFromNBT(NBTTagCompound compound) {

		this.activated = compound.getBoolean("activated");
		this.conquered = compound.getBoolean("conquered");
		this.regenerationTime = compound.getLong("regenerationTime");
		this.lastRegenerationTime = compound.getLong("lastRegenerationTime");
		if (compound.hasKey("shrineElement"))
			this.shrineElement = Element.values()[compound.getInteger("shrineElement")];
		this.linkedContainerPos = NBTUtil.getPosFromTag(compound.getCompoundTag("linkedContainerPos"));

		NBTTagList wizardTagList = compound.getTagList("wizards", Constants.NBT.TAG_COMPOUND);
		int i = 0;
		for (NBTBase tag : wizardTagList) {
			if (tag instanceof NBTTagCompound) linkedWizards[i++] = NBTUtil.getUUIDFromTag((NBTTagCompound) tag);
			else Wizardry.logger.warn("Unexpected tag type in NBT tag list of compound tags!");
		}

		this.lootedPlayers.clear();
		if (compound.hasKey("lootedPlayers")) {
			NBTTagList playerTagList = compound.getTagList("lootedPlayers", Constants.NBT.TAG_COMPOUND);
			for (NBTBase tag : playerTagList) {
				if (tag instanceof NBTTagCompound) lootedPlayers.add(NBTUtil.getUUIDFromTag((NBTTagCompound) tag));
			}
		}

		super.readFromNBT(compound);
		// Must be after super
		initContainmentField(this.pos);
	}

public void tick() {
        boolean flag = this.checkCage();
        if (this.level == null){
            return;
        }
        if (flag) {
            if (this.cursedCageTile.getSouls() > 0){
                RitualRecipe recipe = this.getCurrentRitualRecipe();
                double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                double d1 = (double)this.worldPosition.getY() + this.level.random.nextDouble();
                double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                if (!this.level.isClientSide) {
                    ServerLevel serverWorld = (ServerLevel) this.level;
                    if (recipe != null) {

                        this.restoreCastingPlayer();

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            for (int p = 0; p < 4; ++p) {
                                serverWorld.sendParticles(ParticleTypes.FLAME, d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                            }
                        }

                        ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);

                        if (this.remainingAdditionalIngredients == null) {
                            this.restoreRemainingAdditionalIngredients();
                            if (this.remainingAdditionalIngredients == null) {
                                Goety.LOGGER
                                        .warn("Could not restore remainingAdditionalIngredients during tick - world seems to be null. Will attempt again next tick.");
                                return;
                            }
                        }

                        if (recipe.getRitual().isPending(this)) {
                            return;
                        }

                        IItemHandler handler = this.itemStackHandler.orElseThrow(RuntimeException::new);
                        if (!recipe.getRitual().isValid(this.level, this.worldPosition, this, this.castingPlayer,
                                handler.getStackInSlot(0), this.remainingAdditionalIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            return;
                        }

                        if (this.level.getGameTime() % 20 == 0) {
                            if (this.cursedCageTile.getSouls() >= recipe.getSoulCost()){
                                this.cursedCageTile.decreaseSouls(recipe.getSoulCost());
                                serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F);
                                serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double)this.worldPosition.getX() + 0.5D, (double)this.worldPosition.getY() + 1.15D, (double)this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                this.currentTime++;
                            } else {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noSouls.fail"), true);
                                this.stopRitual(false);
                                return;
                            }
                        }

                        if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual) {
                            if (this.experienceTaken < enchantItemRitual.getLevelCost(handler.getStackInSlot(0))) {
                                if (this.castingPlayer.experienceLevel > 1) {
                                    if (this.level.getGameTime() % 10 == 0) {
                                        serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 0.5F, 0.5F);
                                        this.castingPlayer.giveExperienceLevels(-1);
                                        this.experienceTaken += 1;
                                    }
                                    this.addXPParticles(serverWorld);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noXP.fail"), true);
                                    this.stopRitual(false);
                                    return;
                                }
                            }
                        }

                        recipe.getRitual().update(this.level, this.worldPosition, this, this.castingPlayer, handler.getStackInSlot(0),
                                this.currentTime, recipe.getDuration());

                        if (!recipe.getRitual()
                                .consumeAdditionalIngredients(this.level, this.worldPosition, this.castingPlayer, this.remainingAdditionalIngredients,
                                        this.currentTime, this.consumedIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (recipe.getDuration() >= 0 && this.currentTime >= recipe.getDuration()) {
                            if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual){
                                if (this.experienceTaken >= enchantItemRitual.getLevelCost(handler.getStackInSlot(0))){
                                    this.stopRitual(true);
                                }
                            } else if (!recipe.isConversion()) {
                                this.stopRitual(true);
                            } else {
                                if (this.getConvertEntity != null){
                                    this.stopRitual(true);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            }
                        }

                        int totalTime = 60;

                        if (!RitualRequirements.getProperStructure(recipe.getCraftType(), this.castingPlayer, this, this.worldPosition, this.level)){
                            ++this.structureTime;
                            if (this.structureTime >= totalTime) {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.structure.fail"), true);
                                this.stopRitual(false);
                            }
                        } else {
                            this.structureTime = 0;
                        }
                        if (recipe.isConversion()){
                            if (RitualRequirements.noConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level)){
                                ++this.convertTime;
                                if (this.getConvertEntity != null){
                                    this.getConvertEntity = null;
                                }
                                if (this.convertTime >= totalTime) {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            } else {
                                this.getConvertEntity = RitualRequirements.getConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level);
                                this.convertTime = 0;
                            }
                        }
                    } else {
                        if (this.level.getGameTime() % 20 == 0) {
                            ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);
                        }
                    }
                }
            } else {
                this.stopRitual(false);
            }
        } else {
            this.stopRitual(false);
        }
        this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(DarkAltarBlock.LIT, flag), 3);
    }

public void startRitual(Player player, ItemStack activationItem, RitualRecipe ritualRecipe) {
        if (this.level == null) {
            return;
        }
        if (!this.level.isClientSide) {
            this.currentRitualRecipe = ritualRecipe;
            this.castingPlayerId = player.getUUID();
            this.castingPlayer = player;
            this.currentTime = 0;
            this.sacrificeProvided = false;
            this.consumedIngredients.clear();
            this.remainingAdditionalIngredients = new ArrayList<>(this.currentRitualRecipe.getIngredients());
            IItemHandler handler = this.itemStackHandler.orElseThrow(RuntimeException::new);
            handler.insertItem(0, activationItem.split(1), false);
            this.currentRitualRecipe.getRitual().start(this.level, this.worldPosition, this, player, handler.getStackInSlot(0));
            this.structureTime = 40;
            this.setChanged();
            this.markNetworkDirty();
        }
    }

public void stopRitual(boolean finished) {
        if (this.level == null) {
            return;
        }
        if (!this.level.isClientSide) {
            RitualRecipe recipe = this.getCurrentRitualRecipe();
            if (recipe != null && this.castingPlayer != null) {
                IItemHandler handler = this.itemStackHandler.orElseThrow(RuntimeException::new);
                if (finished) {
                    ItemStack activationItem = handler.getStackInSlot(0);
                    recipe.getRitual().finish(this.level, this.worldPosition, this, this.castingPlayer, activationItem);
                } else {
                    recipe.getRitual().interrupt(this.level, this.worldPosition, this, this.castingPlayer,
                            handler.getStackInSlot(0));
                    Containers.dropItemStack(this.level, this.worldPosition.getX(), this.worldPosition.getY(), this.worldPosition.getZ(),
                            handler.extractItem(0, 1, false));
                }
            }
            this.clearRitual();
            this.setChanged();
            this.markNetworkDirty();
        }
    }

public void clearRitual() {
        if (this.level == null) {
            return;
        }
        if (!this.level.isClientSide) {
            this.currentRitualRecipe = null;
            this.castingPlayerId = null;
            this.castingPlayer = null;
            this.currentTime = 0;
            this.sacrificeProvided = false;
            if (this.remainingAdditionalIngredients != null) {
                this.remainingAdditionalIngredients.clear();
            }
            this.consumedIngredients.clear();
            this.structureTime = 0;
            this.experienceTaken = 0;
            this.findStructurePos = null;
            if (this.pendingStructureSearch != null) {
                this.pendingStructureSearch.cancel(true);
                this.pendingStructureSearch = null;
            }
            this.structureSearchFailed = false;
        }
    }

public void restoreCastingPlayer() {
        if (this.castingPlayer == null && this.castingPlayerId != null) {
            if (this.level != null) {
                if (this.level.getGameTime() % (20 * 30) == 0) {
                    this.castingPlayer = EntityFinder.getPlayerByUuiDGlobal(this.castingPlayerId).orElse(null);
                    this.setChanged();
                    this.markNetworkDirty();
                }
            }
        }
    }

@Override
    public boolean isValid(Level world, BlockPos darkAltarPos, DarkAltarBlockEntity tileEntity,
                           Player castingPlayer, ItemStack activationItem,
                           List<Ingredient> remainingAdditionalIngredients) {
        if (world instanceof ServerLevel serverLevel) {
            if (this.recipe.getStructureTag() == null) {
                return false;
            }
            if (!this.areAdditionalIngredientsFulfilled(world, darkAltarPos, castingPlayer, remainingAdditionalIngredients)) {
                return false;
            }

            if (tileEntity.findStructurePos != null) {
                return true;
            }

            if (tileEntity.structureSearchFailed) {
                castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.location.fail"), true);
                tileEntity.structureSearchFailed = false;
                return false;
            }

            if (tileEntity.pendingStructureSearch != null) {
                if (!tileEntity.pendingStructureSearch.isDone()) {
                    return true;
                }
                BlockPos result = tileEntity.pendingStructureSearch.getNow(null);
                tileEntity.pendingStructureSearch = null;
                if (result != null) {
                    tileEntity.findStructurePos = result;
                } else {
                    tileEntity.structureSearchFailed = true;
                }
                return true;
            }
            final TagKey<Structure> structureTag = this.recipe.getStructureTag();
            final BlockPos searchCenter = darkAltarPos;

            tileEntity.pendingStructureSearch = CompletableFuture.supplyAsync(() ->
                    serverLevel.findNearestMapStructure(structureTag, searchCenter, 100, true)
            );

            return true;
        }
        return false;
    }

public boolean identify(Level world, BlockPos darkAltarPos, Player player, ItemStack activationItem) {
        return this.recipe.getStructureTag() != null
                && this.areAdditionalIngredientsFulfilled(world, darkAltarPos, player, this.recipe.getIngredients());
    }

@Override
    public void interrupt(Level world, BlockPos darkAltarPos, DarkAltarBlockEntity tileEntity, Player castingPlayer, ItemStack activationItem) {
        super.interrupt(world, darkAltarPos, tileEntity, castingPlayer, activationItem);
        tileEntity.findStructurePos = null;
        if (tileEntity.pendingStructureSearch != null) {
            tileEntity.pendingStructureSearch.cancel(true);
            tileEntity.pendingStructureSearch = null;
        }
        tileEntity.structureSearchFailed = false;
    }

@Override
    public boolean isPending(DarkAltarBlockEntity tileEntity) {
        return tileEntity.pendingStructureSearch != null
                && !tileEntity.pendingStructureSearch.isDone();
    }

@Override
    public void finish(Level world, BlockPos blockPos, DarkAltarBlockEntity tileEntity,
                       Player castingPlayer, ItemStack activationItem) {
        super.finish(world, blockPos, tileEntity, castingPlayer, activationItem);

        activationItem.shrink(1);
        if (world instanceof ServerLevel serverLevel) {
            BlockPos structure = tileEntity.findStructurePos;
            if (structure != null) {
                ItemStack result = MapItem.create(serverLevel, structure.getX(), structure.getZ(), (byte) 2, true, true);
                MapItem.renderBiomePreviewMap(serverLevel, result);
                MapItemSavedData.addTargetDecoration(result, structure, "+", MapDecoration.Type.TARGET_POINT);
                String string = "filled_map.goety.magic";
                if (this.recipe.getStructureName() != null) {
                    string = this.recipe.getStructureName();
                }
                result.setHoverName(Component.translatable(string));
                IItemHandler handler = tileEntity.itemStackHandler.orElseThrow(RuntimeException::new);
                handler.insertItem(0, result, false);
                result.onCraftedBy(world, castingPlayer, 1);
                tileEntity.findStructurePos = null;
            }
        }

    }

public void entityInside(BlockState pState, Level pLevel, BlockPos pPos, Entity pEntity) {
        if (pState.getValue(LIT)) {
            if (!pEntity.fireImmune()
                    && pEntity instanceof LivingEntity livingEntity
                    && livingEntity.getMobType() != MobType.UNDEAD
                    && !LichdomHelper.isInLichMode(livingEntity)
                    && !EnchantmentHelper.hasFrostWalker((LivingEntity) pEntity)
                    && pEntity.getY() >= pPos.getY() + 0.5F) {
                pEntity.hurt(pEntity.damageSources().inFire(), 1.0F);
            }
            BlockEntity tileentity = pLevel.getBlockEntity(pPos);
            if (tileentity instanceof NecroBrazierBlockEntity blockEntity) {
                if (pEntity instanceof ItemEntity itemEntity) {
                    if (!pLevel.isClientSide) {
                        if (itemEntity.isAlive() && !itemEntity.getItem().isEmpty() && !itemEntity.getTags().contains(ConstantPaths.resultItem())) {
                            if (blockEntity.currentTime <= 0) {
                                if (blockEntity.addItem(null, itemEntity.getItem())) {
                                    pLevel.playSound(null, pPos, SoundEvents.ITEM_PICKUP, SoundSource.BLOCKS, 1.0F, 1.0F);
                                    syncItem(itemEntity);
                                }
                            }
                        }
                    }
                }
            }
        }

        super.entityInside(pState, pLevel, pPos, pEntity);
    }

public boolean addItem(@Nullable Player player, ItemStack stack) {
        if (this.currentTime > 0){
            return false;
        }

        boolean did = false;

        for (int i = 0; i < this.getContainer().getContainerSize(); i++) {
            if (this.getContainer().getItem(i).isEmpty()) {
                did = true;
                ItemStack stackToAdd = stack.copyWithCount(1);
                this.getContainer().setItem(i, stackToAdd);

                if (player == null || !player.getAbilities().instabuild) {
                    stack.shrink(1);
                }

                break;
            }
        }
        if (did) {
            if (player != null && this.level != null){
                this.level.playSound(null, this.getBlockPos(), SoundEvents.ARMOR_EQUIP_GENERIC, SoundSource.BLOCKS, 1.0F, 1.0F);
            }
            this.markUpdated();
        }
        return did;
    }

public void tick() {
        if (this.level != null) {
            boolean flag = this.level.getBiome(this.getBlockPos()).is(Biomes.DEEP_DARK);
            if (flag) {
                this.findCandlesticks();
                if (!this.level.isClientSide) {
                    if (this.level.random.nextFloat() < 0.3F) {
                        if (this.level.random.nextFloat() < 0.17F) {
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FURNACE_FIRE_CRACKLE, 0.5F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                        }
                    }
                }
                if (!this.candlestickBlockEntityList.isEmpty()){
                    BrazierRecipe recipe = this.getRecipe();
                    double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                    double d1 = (double)this.worldPosition.getY() + 0.5D + this.level.random.nextDouble();
                    double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                    if (!this.level.isClientSide) {
                        ServerLevel serverWorld = (ServerLevel) this.level;
                        this.makeParticles();
                        if (this.activate(this.level)) {
                            if (recipe != null) {
                                for (int p = 0; p < 2; ++p) {
                                    serverWorld.sendParticles(ModParticleTypes.SMALL_NECRO_FIRE.get(), d0, this.worldPosition.getY() + 0.5F, d2, 1, 0, 0, 0, 0);
                                    serverWorld.sendParticles(ParticleTypes.SMOKE, d0, d1, d2, 0, 0.0D, 5.0E-4D, 0.0D, 0.5F);
                                    serverWorld.sendParticles(ModParticleTypes.NECRO_EFFECT.get(), d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                                }
                                for (BlockEntity blockEntity : this.candlestickBlockEntityList){
                                    if (blockEntity instanceof ISoulCandle soulCandle) {
                                        if (soulCandle.getSouls() > 0) {
                                            soulCandle.drainSouls(this.getBlockPos());
                                            this.currentTime += soulCandle.soulDrainAmount();
                                        }
                                    }
                                }
                                if (!this.playSound) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.BLAZE_AMBIENT, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    this.playSound = true;
                                }
                                if (this.level.getGameTime() % 20 == 0) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FIRE_AMBIENT, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double) this.worldPosition.getX() + 0.5D, (double) this.worldPosition.getY() + 1.15D, (double) this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                }

                                if (this.currentTime >= recipe.getSoulCost()) {
                                    this.stopBrazier(true);
                                } else {
                                    this.updateRecipe(this.level);
                                }
                            }
                        }
                    }
                } else {
                    if (!this.level.isClientSide) {
                        this.stopBrazier(false);
                    }
                }
            } else {
                if (!this.level.isClientSide) {
                    this.stopBrazier(false);
                }
            }
            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(NecroBrazierBlock.LIT, flag), 3);
        }
    }

public BrazierRecipe getRecipe(){
        if(this.recipeId != null){
            if(this.level != null) {
                Optional<? extends Recipe<?>> recipe = this.level.getRecipeManager().byKey(this.recipeId);
                recipe.map(r -> (BrazierRecipe) r).ifPresent(r -> this.recipe = r);
                this.recipeId = null;
            }
        }
        return this.recipe;
    }

public boolean activate(Level world) {
        if (this.getRecipe() == null) {
            BrazierRecipe brazierRecipe = world.getRecipeManager().getAllRecipesFor(ModRecipeSerializer.BRAZIER_TYPE.get()).stream().filter(
                    r -> r.matches(this.getContainer(), world)
            ).findFirst().orElse(null);
            if (brazierRecipe != null) {
                this.recipe = brazierRecipe;
            } else {
                return false;
            }
        }
        return true;
    }

public void updateRecipe(Level world){
        if (this.getRecipe() != null){
            if (!this.getRecipe().matches(this.getContainer(), world)){
                this.stopBrazier(false);
            }
        } else {
            this.stopBrazier(false);
        }
    }

public void stopBrazier(boolean finished) {
        if (this.level != null) {
            if (!this.level.isClientSide) {
                BrazierRecipe recipe = this.getRecipe();
                if (recipe != null) {
                    this.level.playSound(null, this.getBlockPos(), SoundEvents.GENERIC_EXTINGUISH_FIRE, SoundSource.BLOCKS, 1.0F, 1.0F);
                    if (finished) {
                        ItemStack itemstack1 = this.level.getRecipeManager()
                                .getRecipeFor(ModRecipeSerializer.BRAZIER_TYPE.get(), this.getContainer(), this.level)
                                .map((recipes) -> recipes.assemble(this.getContainer(), this.level.registryAccess())).orElse(ItemStack.EMPTY);
                        BlockPos blockpos = this.getBlockPos();
                        dropItemStack(this.level, blockpos.getX(), blockpos.getY() + 1, blockpos.getZ(), itemstack1);
                        this.level.playSound(null, this.getBlockPos(), ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 2.0F, 0.5F);
                    } else {
                        if (!this.isEmpty()) {
                            Containers.dropContents(this.level, this.getBlockPos(), this.getItems());
                            this.level.playSound(null, this.getBlockPos(), ModSounds.SPELL_FAIL.get(), SoundSource.BLOCKS, 2.0F, 0.5F);
                        }
                    }
                } else {
                    if (!this.isEmpty()) {
                        Containers.dropContents(this.level, this.getBlockPos(), this.getItems());
                        this.level.playSound(null, this.getBlockPos(), ModSounds.SPELL_FAIL.get(), SoundSource.BLOCKS, 2.0F, 0.5F);
                    }
                }
                this.removeAllItems();
                this.clearContent();
                this.recipe = null;
                this.currentTime = 0;
                this.playSound = false;
                this.markUpdated();
            }
        }
    }

public static void dropItemStack(Level pLevel, double pX, double pY, double pZ, ItemStack pStack) {
        double d0 = (double) EntityType.ITEM.getWidth();
        double d1 = 1.0D - d0;
        double d2 = d0 / 2.0D;
        double d3 = Math.floor(pX) + pLevel.random.nextDouble() * d1 + d2;
        double d4 = Math.floor(pY) + pLevel.random.nextDouble() * d1;
        double d5 = Math.floor(pZ) + pLevel.random.nextDouble() * d1 + d2;

        while(!pStack.isEmpty()) {
            ItemEntity itementity = new ItemEntity(pLevel, d3, d4, d5, pStack.split(pLevel.random.nextInt(21) + 10));
            itementity.addTag(ConstantPaths.resultItem());
            itementity.setDeltaMovement(pLevel.random.triangle(0.0D, 0.11485000171139836D), pLevel.random.triangle(0.2D, 0.11485000171139836D), pLevel.random.triangle(0.0D, 0.11485000171139836D));
            pLevel.addFreshEntity(itementity);
        }

    }

public void removeAllItems(){
        for (int i = 0; i < this.getContainer().getContainerSize(); i++) {
            ItemStack stackAt = this.getContainer().getItem(i);
            if (!stackAt.isEmpty()) {
                this.getContainer().setItem(i, ItemStack.EMPTY);
            }
        }
    }

@Override
    public void clearContent() {
        this.getItems().clear();
    }
